static void Gen_stbox_to_geo(DataChunk &args, ExpressionState &state, Vector &result) {
    EnsureMeosThreadInitialized();
    UnaryExecutor::ExecuteWithNulls<string_t, string_t>(args.data[0], result, args.size(),
        [&](string_t in, ValidityMask &mask, idx_t idx) -> string_t {
            STBox *s = BlobToStbox(in);
            GSERIALIZED *r = stbox_to_geo(s);
            free(s);
            if (!r) { mask.SetInvalid(idx); return string_t(); }
            string_t out = GSerializedToGeometry(r, state, result);
            free(r);
            return out;
        });
}


// ===== @ingroup meos_geo_rel_temp =====
static void Gen_tcontains_geo_tgeo(DataChunk &args, ExpressionState &, Vector &result) {
    EnsureMeosThreadInitialized();
    BinaryExecutor::ExecuteWithNulls<string_t, string_t, string_t>(args.data[0], args.data[1], result, args.size(),
        [&](string_t in_g, string_t in_t, ValidityMask &mask, idx_t idx) -> string_t {
            Temporal *t = BlobToTemporal(in_t);
            GSERIALIZED *gs = GeometryToGSerialized(in_g, tspatial_srid(t));
            if (MEOS_FLAGS_GET_GEODETIC(t->flags)) {
                GSERIALIZED *gs_geog = geom_to_geog(gs);
                free(gs); gs = gs_geog;
            }
            Temporal *r = (Temporal *) tcontains_geo_tgeo(gs, t);
            free(t); free(gs);
            return TemporalToBlobN(result, r, mask, idx);
        });
}

